    const data = [];
    tables.forEach((table, tableIndex) => {
        const rows = table.querySelectorAll('tbody tr');
        rows.forEach(row => {
            const cells = row.querySelectorAll('td');
            if (cells.length >= 2) {
                const yearCell = cells[0];
                const year = yearCell.textContent.trim();
                if (/^\d{4}$/.test(year)) {
                    const albumCell = cells[1];
                    const album = albumCell.textContent.trim();
                    data.push({tableIndex, year, album});
                }
            }
        });
    });
    return data;
}"}

