    const results = [];
    for (let i = 0; i < 10; i++) {
        // Reload the page to ensure fresh fetch
        await page.reload();
        // Wait for table
        await page.waitForSelector('table.wikitable');
        const data = await page.evaluate(() => {
            const tables = Array.from(document.querySelectorAll('table.wikitable'));
            const data = [];
            tables.forEach((table, tableIndex) => {
                const rows = table.querySelectorAll('tbody tr');
                rows.forEach(row => {
                    const cells = row.querySelectorAll('td');
                    if (cells.length >= 2) {
                        const yearCell = cells[0];
                        const year = yearCell.textContent.trim();
                        if (/^\d{4}$/.test(year)) {
                            const albumCell = cells[1];
                            const album = albumCell.textContent.trim();
                            data.push({tableIndex, year, album});
                        }
                    }
                });
            });
            return data;
        });
        // Filter studio albums (tableIndex 0)
        const studioAlbums = data.filter(item => item.tableIndex === 0).map(item => ({year: item.year, album: item.album}));
        results.push(studioAlbums);
    }
    // Check consistency
    const first = JSON.stringify(results[0]);
    let allIdentical = true;
    for (let i = 1; i < results.length; i++) {
        if (JSON.stringify(results[i]) !== first) {
            allIdentical = false;
            break;
        }
    }
    return {allIdentical, results};
}"}

