    // Find the table for studio albums - there may be multiple tables, but we can locate by heading "Studio albums"
    const headings = Array.from(document.querySelectorAll('h3'));
    let studioHeading = null;
    for (let h of headings) {
        if (h.textContent.includes('Studio albums')) {
            studioHeading = h;
            break;
        }
    }
    if (!studioHeading) return null;
    // Find the next table after this heading
    let elem = studioHeading.nextElementSibling;
    while (elem && elem.tagName !== 'TABLE') {
        elem = elem.nextElementSibling;
    }
    if (!elem) return null;
    const rows = elem.querySelectorAll('tbody tr');
    const data = [];
    rows.forEach(row => {
        const cells = row.querySelectorAll('td');
        if (cells.length >= 2) {
            const yearCell = cells[0];
            const detailsCell = cells[1];
            const year = yearCell.textContent.trim();
            const album = detailsCell.textContent.trim();
            data.push({year, album});
        } else {
            // header row
            const ths = row.querySelectorAll('th');
            if (ths.length >= 2) {
                // skip header
            }
        }
    });
    return data;
}"}

