{"function": "() => {
    const rawText = document.body.textContent;
    // Find the studio albums section
    const startMarker = '=== Studio albums ===';
    const endMarker = '=== EPs ===';
    const startIndex = rawText.indexOf(startMarker);
    const endIndex = rawText.indexOf(endMarker);
    if (startIndex === -1 || endIndex === -1) return 'Section not found';
    const section = rawText.substring(startIndex, endIndex);
    // Extract lines with year patterns
    const lines = section.split('\\n');
    const albums = [];
    for (const line of lines) {
        // Look for lines starting with "|" and containing year
        if (line.startsWith('|') && line.includes('|')) {
            const parts = line.split('|').map(p => p.trim()).filter(p => p);
            if (parts.length >= 2) {
                const yearPart = parts[0];
                const detailsPart = parts[1];
                const yearMatch = yearPart.match(/\\d{4}/);
                if (yearMatch) {
                    const year = parseInt(yearMatch[0]);
                    if (year >= 2000 && year <= 2009) {
                        albums.push({year, details: detailsPart});
                    }
                }
            }
        }
    }
    return albums;
}"}

