    const startMarker = '=== Studio albums ===';
    const startIdx = rawText.indexOf(startMarker);
    if (startIdx === -1) return 'Start not found';
    const afterStart = rawText.substring(startIdx);
    const tableStart = afterStart.indexOf('{| class=\"wikitable\"');
    if (tableStart === -1) return 'Table start not found';
    const tableEnd = afterStart.indexOf('|}', tableStart);
    if (tableEnd === -1) return 'Table end not found';
    const tableText = afterStart.substring(tableStart, tableEnd + 2);
    // Split lines
    const lines = tableText.split('\\n');
    const albums = [];
    let inRow = false;
    for (const line of lines) {
        const trimmed = line.trim();
        if (trimmed.startsWith('|+')) continue; // caption
        if (trimmed.startsWith('|-')) {
            inRow = true;
            continue;
        }
        if (inRow && trimmed.startsWith('|')) {
            // row cells separated by '|'
            const cells = trimmed.split('|').slice(1).map(c => c.trim()).filter(c => c);
            if (cells.length >= 2) {
                const yearCell = cells[0];
